\margin{L'intérêt principal de cette factorisation, c'est que \unsure{l'inclusion}''
\begin{tikzcd}[ampersand replacement=\&,column sep=small,cramped]
Y\arrow[r,-,to path={(\tikztostart)--(\tikztotarget) node[circle,fill=black,inner sep=.45pt] {} \tikztonodes}]\&\mathcal V_{Y,X}
\end{tikzcd}
est une équivalence d'homotopie'' (indépendamment de toute hyp. de locale trivialité)}

\begin{tikzcd}[ampersand replacement=\&,column sep=small,cramped]
