(11) $\mathcal V^*_{Y,X}\longrightarrow\mathcal V_{Y,X}$ est une ``fibration homotopique'' de fibre $\mathcal V^*_{z,X}$, de base
\begin{tikzcd}[ampersand replacement=\&,cramped,column sep=4em]
Y\arrow[r,-,"{\approx\,\mathrm{homot}}",to path={(\tikztostart) ++(.1,.055) .. controls +(-.12,.05) and +(-.12,0) .. ++(0,-.055) -- (\tikztotarget) (\tikztostart) ++(.33,0) -- ++(.12,-.025) -- ++(.16,.025) (\tikztotarget) ++(-.01,.04) .. controls +(.06,0) and +(.06,0) .. ++(0,-.08) \tikztonodes}]\&\mathcal V_{Y,\unsure{\lambda|X}}
\end{tikzcd}

\begin{tikzcd}[ampersand replacement=\&,cramped,column sep=4em]
Y\arrow[r,-,"{\approx\,\mathrm{homot}}",to path={(\tikztostart) ++(.1,.055) .. controls +(-.12,.05) and +(-.12,0) .. ++(0,-.055) -- (\tikztotarget) (\tikztostart) ++(.33,0) -- ++(.12,-.025) -- ++(.16,.025) (\tikztotarget) ++(-.01,.04) .. controls +(.06,0) and +(.06,0) .. ++(0,-.08) \tikztonodes}]\&\mathcal V_{Y,\unsure{\lambda|X}}
